const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // Define regions for northern and southern Kenya
  const northKenya = ee.Geometry.Polygon([
    [[36.0, 4.0], [41.0, 4.0], [41.0, 5.0], [36.0, 5.0], [36.0, 4.0]]
  ]);

  const southKenya = ee.Geometry.Polygon([
    [[36.0, -4.0], [41.0, -4.0], [41.0, -1.0], [36.0, -1.0], [36.0, -4.0]]
  ]);

  // Get MODIS NDVI data for May-June 2019
  const ndviCollection = ee.ImageCollection('MODIS/061/MOD13Q1')
    .filterDate('2019-05-01', '2019-07-01')
    .select('NDVI');

  // Check if collection is empty
  const collectionSize = ndviCollection.size().getInfo();
  console.log(`MODIS NDVI images found: ${collectionSize}`);

  if (collectionSize === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Calculate mean NDVI composite
  const meanNdvi = ndviCollection.mean().multiply(0.0001); // Apply scale factor

  // Calculate mean NDVI for each region
  const northStats = meanNdvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: northKenya,
    scale: 1000,
    maxPixels: 1e9
  });

  const southStats = meanNdvi.reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: southKenya,
    scale: 1000,
    maxPixels: 1e9
  });

  // Get pixel counts to validate data
  const northCount = meanNdvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: northKenya,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const southCount = meanNdvi.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: southKenya,
    scale: 1000,
    maxPixels: 1e9
  }).get('NDVI').getInfo();

  const northNdvi = northStats.get('NDVI').getInfo();
  const southNdvi = southStats.get('NDVI').getInfo();

  console.log(`North Kenya - NDVI: ${northNdvi?.toFixed(3)}, Pixels: ${northCount}`);
  console.log(`South Kenya - NDVI: ${southNdvi?.toFixed(3)}, Pixels: ${southCount}`);

  // Check for valid pixels
  if (northCount === 0 || southCount === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Validate results
  if (northNdvi === null || southNdvi === null || 
      isNaN(northNdvi) || isNaN(southNdvi) ||
      northNdvi < -1 || northNdvi > 1 || 
      southNdvi < -1 || southNdvi > 1) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Compare NDVI values
  if (northNdvi < southNdvi) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
